let __v_194 = pyrt::literals::decode("{\"$dict\":[[\"australia\",\"Canberra, not Sydney: it was purpose-built as the compromise between Sydney and Melbourne.\"],[\"canada\",\"Ottawa, not Toronto.\"],[\"brazil\",\"Brasília, not Rio, and a planned city built in four years.\"],[\"turkey\",\"Ankara, not Istanbul.\"],[\"switzerland\",\"Bern, the de facto capital; Switzerland has no official one.\"],[\"united states\",\"Washington DC, not New York.\"],[\"usa\",\"Washington DC, not New York.\"],[\"america\",\"Washington DC, not New York.\"],[\"netherlands\",\"Amsterdam, though the government sits in The Hague.\"],[\"france\",\"Paris.\"],[\"spain\",\"Madrid.\"],[\"portugal\",\"Lisbon.\"],[\"italy\",\"Rome.\"],[\"germany\",\"Berlin, since reunification in 1990.\"],[\"japan\",\"Tokyo.\"],[\"china\",\"Beijing.\"],[\"india\",\"New Delhi, not Mumbai.\"],[\"russia\",\"Moscow.\"],[\"new zealand\",\"Wellington, not Auckland.\"],[\"norway\",\"Oslo.\"],[\"sweden\",\"Stockholm.\"],[\"denmark\",\"Copenhagen.\"],[\"finland\",\"Helsinki.\"],[\"greece\",\"Athens.\"],[\"ireland\",\"Dublin.\"],[\"poland\",\"Warsaw.\"],[\"austria\",\"Vienna.\"],[\"belgium\",\"Brussels.\"],[\"hungary\",\"Budapest.\"],[\"czechia\",\"Prague.\"],[\"czech republic\",\"Prague.\"],[\"south korea\",\"Seoul.\"],[\"mexico\",\"Mexico City.\"],[\"argentina\",\"Buenos Aires.\"],[\"south africa\",\"Pretoria, though the parliament sits in Cape Town and the courts in Johannesburg.\"],[\"afghanistan\",\"Kabul.\"],[\"albania\",\"Tirana.\"],[\"algeria\",\"Algiers.\"],[\"andorra\",\"Andorra la Vella.\"],[\"angola\",\"Luanda.\"],[\"antigua and barbuda\",\"Saint John's.\"],[\"armenia\",\"Yerevan.\"],[\"azerbaijan\",\"Baku.\"],[\"bahamas\",\"Nassau.\"],[\"bahrain\",\"Manama.\"],[\"bangladesh\",\"Dhaka.\"],[\"barbados\",\"Bridgetown.\"],[\"belarus\",\"Minsk.\"],[\"belize\",\"Belmopan, not Belize City.\"],[\"benin\",\"Porto-Novo, though the government sits in Cotonou.\"],[\"bhutan\",\"Thimphu.\"],[\"bolivia\",\"Sucre is the constitutional capital; La Paz is where the government sits.\"],[\"bosnia and herzegovina\",\"Sarajevo.\"],[\"bosnia\",\"Sarajevo.\"],[\"botswana\",\"Gaborone.\"],[\"brunei\",\"Bandar Seri Begawan.\"],[\"bulgaria\",\"Sofia.\"],[\"burkina faso\",\"Ouagadougou.\"],[\"burma\",\"Naypyidaw, not Yangon, which was the capital until 2006.\"],[\"burundi\",\"Gitega, since 2019; Bujumbura was the capital before that.\"],[\"cambodia\",\"Phnom Penh.\"],[\"cameroon\",\"Yaounde.\"],[\"cape verde\",\"Praia.\"],[\"central african republic\",\"Bangui.\"],[\"chad\",\"N'Djamena.\"],[\"chile\",\"Santiago.\"],[\"colombia\",\"Bogota.\"],[\"comoros\",\"Moroni.\"],[\"congo\",\"Two countries share the name: Brazzaville for the Republic of the Congo, Kinshasa for the Democratic Republic of the Congo.\"],[\"costa rica\",\"San Jose.\"],[\"cote d'ivoire\",\"Yamoussoukro, not Abidjan.\"],[\"croatia\",\"Zagreb.\"],[\"cuba\",\"Havana.\"],[\"cyprus\",\"Nicosia.\"],[\"democratic republic of the congo\",\"Kinshasa.\"],[\"djibouti\",\"Djibouti.\"],[\"dominica\",\"Roseau - not Santo Domingo, which is the Dominican Republic's capital.\"],[\"dominican republic\",\"Santo Domingo.\"],[\"dr congo\",\"Kinshasa.\"],[\"ecuador\",\"Quito.\"],[\"el salvador\",\"San Salvador.\"],[\"equatorial guinea\",\"Malabo.\"],[\"eritrea\",\"Asmara.\"],[\"estonia\",\"Tallinn.\"],[\"eswatini\",\"Mbabane for the administration, Lobamba for the parliament; the country was called Swaziland until 2018.\"],[\"ethiopia\",\"Addis Ababa.\"],[\"fiji\",\"Suva.\"],[\"gabon\",\"Libreville.\"],[\"gambia\",\"Banjul.\"],[\"georgia\",\"Tbilisi - the country's capital. The US state of Georgia has Atlanta.\"],[\"ghana\",\"Accra.\"],[\"grenada\",\"St George's.\"],[\"guatemala\",\"Guatemala City.\"],[\"guinea\",\"Conakry.\"],[\"guinea-bissau\",\"Bissau.\"],[\"guyana\",\"Georgetown.\"],[\"haiti\",\"Port-au-Prince.\"],[\"holland\",\"Amsterdam, though the government sits in The Hague.\"],[\"honduras\",\"Tegucigalpa.\"],[\"indonesia\",\"Jakarta, though the government is moving to a new capital, Nusantara, in Borneo.\"],[\"iran\",\"Tehran.\"],[\"iraq\",\"Baghdad.\"],[\"israel\",\"Jerusalem, which Israel calls its capital; most countries keep their embassies in Tel Aviv because the status is disputed.\"],[\"ivory coast\",\"Yamoussoukro, not Abidjan, which is the biggest city.\"],[\"jamaica\",\"Kingston.\"],[\"jordan\",\"Amman.\"],[\"kazakhstan\",\"Astana, which was called Nur-Sultan from 2019 to 2022.\"],[\"kiribati\",\"South Tarawa.\"],[\"kuwait\",\"Kuwait City.\"],[\"kyrgyzstan\",\"Bishkek.\"],[\"laos\",\"Vientiane.\"],[\"latvia\",\"Riga.\"],[\"lebanon\",\"Beirut.\"],[\"lesotho\",\"Maseru.\"],[\"liberia\",\"Monrovia.\"],[\"libya\",\"Tripoli.\"],[\"liechtenstein\",\"Vaduz.\"],[\"lithuania\",\"Vilnius.\"],[\"luxembourg\",\"Luxembourg City.\"],[\"madagascar\",\"Antananarivo.\"],[\"malawi\",\"Lilongwe.\"],[\"malaysia\",\"Kuala Lumpur, though the government sits in Putrajaya.\"],[\"maldives\",\"Male.\"],[\"mali\",\"Bamako.\"],[\"malta\",\"Valletta.\"],[\"marshall islands\",\"Majuro.\"],[\"mauritania\",\"Nouakchott.\"],[\"mauritius\",\"Port Louis.\"],[\"micronesia\",\"Palikir.\"],[\"moldova\",\"Chisinau.\"],[\"monaco\",\"Monaco itself - the country is one city.\"],[\"mongolia\",\"Ulaanbaatar.\"],[\"montenegro\",\"Podgorica.\"],[\"mozambique\",\"Maputo.\"],[\"myanmar\",\"Naypyidaw, not Yangon, which was the capital until 2006.\"],[\"namibia\",\"Windhoek.\"],[\"nauru\",\"Yaren, where the government sits; Nauru has no official capital.\"],[\"nepal\",\"Kathmandu.\"],[\"nicaragua\",\"Managua.\"],[\"niger\",\"Niamey.\"],[\"north korea\",\"Pyongyang.\"],[\"north macedonia\",\"Skopje.\"],[\"oman\",\"Muscat.\"],[\"pakistan\",\"Islamabad, not Karachi.\"],[\"palau\",\"Ngerulmud, a purpose-built capital; the biggest town is Koror.\"],[\"panama\",\"Panama City.\"],[\"papua new guinea\",\"Port Moresby.\"],[\"paraguay\",\"Asuncion.\"],[\"peru\",\"Lima.\"],[\"philippines\",\"Manila, not Quezon City, which is the bigger city.\"],[\"qatar\",\"Doha.\"],[\"romania\",\"Bucharest.\"],[\"rwanda\",\"Kigali.\"],[\"saint kitts and nevis\",\"Basseterre.\"],[\"saint lucia\",\"Castries.\"],[\"saint vincent and the grenadines\",\"Kingstown.\"],[\"samoa\",\"Apia.\"],[\"american samoa\",\"Pago Pago, on Tutuila - a US territory of its own, not Samoa, whose capital is Apia.\"],[\"guam\",\"Hagåtña, a US territory in the Pacific.\"],[\"puerto rico\",\"San Juan, a US territory, not a state.\"],[\"bermuda\",\"Hamilton, a British territory - not Hamilton, Ontario.\"],[\"san marino\",\"San Marino.\"],[\"sao tome and principe\",\"Sao Tome.\"],[\"saudi arabia\",\"Riyadh.\"],[\"senegal\",\"Dakar.\"],[\"serbia\",\"Belgrade.\"],[\"seychelles\",\"Victoria.\"],[\"sierra leone\",\"Freetown.\"],[\"singapore\",\"Singapore itself - the country is one city.\"],[\"slovakia\",\"Bratislava.\"],[\"slovenia\",\"Ljubljana.\"],[\"solomon islands\",\"Honiara.\"],[\"somalia\",\"Mogadishu.\"],[\"south sudan\",\"Juba.\"],[\"sri lanka\",\"Sri Jayawardenepura Kotte, though Colombo is the one everyone names.\"],[\"sudan\",\"Khartoum.\"],[\"suriname\",\"Paramaribo.\"],[\"swaziland\",\"Mbabane for the administration and Lobamba for the parliament; the country is called Eswatini now.\"],[\"syria\",\"Damascus.\"],[\"taiwan\",\"Taipei.\"],[\"tajikistan\",\"Dushanbe.\"],[\"tanzania\",\"Dodoma, not Dar es Salaam, which is the biggest city.\"],[\"thailand\",\"Bangkok.\"],[\"timor-leste\",\"Dili.\"],[\"togo\",\"Lome.\"],[\"tonga\",\"Nuku'alofa.\"],[\"trinidad and tobago\",\"Port of Spain.\"],[\"tunisia\",\"Tunis.\"],[\"turkmenistan\",\"Ashgabat.\"],[\"tuvalu\",\"Funafuti.\"],[\"uae\",\"Abu Dhabi, not Dubai.\"],[\"uganda\",\"Kampala.\"],[\"ukraine\",\"Kyiv.\"],[\"united arab emirates\",\"Abu Dhabi, not Dubai.\"],[\"united kingdom\",\"London.\"],[\"uk\",\"London.\"],[\"britain\",\"London.\"],[\"great britain\",\"London, though Great Britain is the island, not the country: the UK is the four nations together.\"],[\"uruguay\",\"Montevideo.\"],[\"uzbekistan\",\"Tashkent.\"],[\"vanuatu\",\"Port Vila.\"],[\"vatican city\",\"Vatican City, which is the whole country.\"],[\"venezuela\",\"Caracas.\"],[\"vietnam\",\"Hanoi, not Ho Chi Minh City.\"],[\"washington\",\"Olympia if you mean the state, Washington DC if you mean the city - the two are different, and neither is New York.\"],[\"yemen\",\"Sanaa.\"],[\"zambia\",\"Lusaka.\"],[\"zimbabwe\",\"Harare.\"],[\"northern ireland\",\"Belfast, not Dublin - Dublin is the capital of the Republic of Ireland.\"],[\"new south wales\",\"Sydney, not Canberra - Canberra is the capital of the country.\"],[\"queensland\",\"Brisbane, not Canberra - Canberra is the capital of the country.\"],[\"south australia\",\"Adelaide, not Canberra - Canberra is the capital of the country.\"],[\"western australia\",\"Perth, not Canberra - Canberra is the capital of the country.\"],[\"tasmania\",\"Hobart, not Canberra - Canberra is the capital of the country.\"],[\"victoria\",\"Melbourne, not Canberra - Canberra is the capital of the country.\"],[\"northern territory\",\"Darwin, not Canberra - Canberra is the capital of the country.\"],[\"scotland\",\"Edinburgh, not London - London is the capital of the UK.\"],[\"wales\",\"Cardiff, not London - London is the capital of the UK.\"],[\"new york state\",\"Albany, not New York City - the city is not the capital of the state.\"],[\"new york\",\"Albany, not New York City - the city is not the capital of the state.\"],[\"california\",\"Sacramento, not Los Angeles or San Francisco.\"],[\"texas\",\"Austin, not Houston or Dallas.\"],[\"florida\",\"Tallahassee, not Miami.\"],[\"illinois\",\"Springfield, not Chicago.\"],[\"pennsylvania\",\"Harrisburg, not Philadelphia.\"],[\"michigan\",\"Lansing, not Detroit.\"],[\"missouri\",\"Jefferson City, not St Louis or Kansas City.\"],[\"maryland\",\"Annapolis, not Baltimore.\"],[\"alaska\",\"Juneau, not Anchorage.\"],[\"washington state\",\"Olympia, not Seattle - and not Washington DC, which is a different city.\"],[\"ohio\",\"Columbus.\"],[\"arizona\",\"Phoenix.\"],[\"colorado\",\"Denver.\"],[\"nevada\",\"Carson City, not Las Vegas.\"],[\"oregon\",\"Salem, not Portland.\"],[\"utah\",\"Salt Lake City.\"],[\"massachusetts\",\"Boston.\"],[\"north carolina\",\"Raleigh.\"],[\"south carolina\",\"Columbia.\"],[\"tennessee\",\"Nashville.\"],[\"virginia\",\"Richmond.\"],[\"minnesota\",\"St Paul, not Minneapolis.\"],[\"wisconsin\",\"Madison, not Milwaukee.\"],[\"indiana\",\"Indianapolis.\"],[\"kentucky\",\"Frankfort, not Louisville.\"],[\"oklahoma\",\"Oklahoma City.\"],[\"iowa\",\"Des Moines.\"],[\"kansas\",\"Topeka, not Wichita.\"],[\"nebraska\",\"Lincoln, not Omaha.\"],[\"idaho\",\"Boise.\"],[\"maine\",\"Augusta, not Portland.\"],[\"new mexico\",\"Santa Fe, not Albuquerque.\"],[\"hawaii\",\"Honolulu.\"],[\"alabama\",\"Montgomery.\"],[\"arkansas\",\"Little Rock.\"],[\"connecticut\",\"Hartford.\"],[\"delaware\",\"Dover.\"],[\"louisiana\",\"Baton Rouge, not New Orleans.\"],[\"mississippi\",\"Jackson.\"],[\"montana\",\"Helena.\"],[\"new hampshire\",\"Concord.\"],[\"new jersey\",\"Trenton.\"],[\"north dakota\",\"Bismarck.\"],[\"rhode island\",\"Providence.\"],[\"south dakota\",\"Pierre.\"],[\"vermont\",\"Montpelier.\"],[\"west virginia\",\"Charleston.\"],[\"wyoming\",\"Cheyenne.\"],[\"england\",\"London.\"],[\"morocco\",\"Rabat, not Casablanca.\"],[\"egypt\",\"Cairo.\"],[\"kenya\",\"Nairobi.\"],[\"nigeria\",\"Abuja, not Lagos.\"],[\"iceland\",\"Reykjavík.\"]]}")?;
frame.store("CAPITALS", __v_194.clone())?;
let __v_195 = pyrt::literals::decode("{\"$dict\":[[\"lisbon\",\"Alfama on foot and the 28 tram, Belém for the tower and the custard tarts, and LX Factory or Time Out Market for lunch. May is warm and busy, so book the tower and the popular restaurants ahead.\"],[\"rome\",\"the Colosseum with a timed ticket, the Pantheon, and Trastevere in the evening for dinner. Book the Vatican museums online, and carry a refillable bottle: the fountains are free.\"],[\"florence\",\"the Duomo climb, the Uffizi (book a slot), and the Oltrarno side of the river for food. Two days is enough for those three if you don't queue for everything.\"],[\"paris\",\"walk the Île de la Cité to the Marais, pick one big museum rather than three, and eat in a market street rather than by the Eiffel Tower. Book the Louvre or Orsay timed entry online.\"],[\"barcelona\",\"the Gothic Quarter, the Sagrada Família (book weeks ahead), and the beach at Barceloneta for half a day. Eat lunch at 2pm like locals; the good places open then.\"],[\"madrid\",\"the Prado, the Retiro park and the tapas streets around Plaza Mayor. Dinner starts late here, so plan on eating at 9pm or later.\"],[\"amsterdam\",\"the Jordaan on foot, the Rijksmuseum and a canal walk at dusk. Book Anne Frank House tickets online weeks ahead; they sell out completely.\"],[\"berlin\",\"the Wall memorial and East Side Gallery, Museum Island, and Kreuzberg for food. It's a big, spread-out city, so buy a day travel ticket.\"],[\"prague\",\"the Old Town at 7am before the crowds, Charles Bridge early, and the castle on the hill. Beer is cheaper than water, but change money at a bank, not a kiosk.\"],[\"vienna\",\"the Ringstrasse, one grand coffee house and the Naschmarkt. Book the Spanish Riding School or a concert only if you're sure: they are pricey.\"],[\"edinburgh\",\"the Royal Mile and the castle, Arthur's Seat for the view, and Leith for food. In December it's dark by 4pm and the Christmas market fills the centre.\"],[\"london\",\"pick one area a day rather than criss-crossing: South Bank, the museums in South Kensington, and the markets in the East End. The Tube is quickest; walking between central stops is often as fast.\"],[\"dublin\",\"a walk through Trinity College and the Book of Kells, the Guinness Storehouse, and pubs away from Temple Bar for music. Book the Book of Kells online.\"],[\"porto\",\"the river walk to Ribeira, a port cellar tour in Gaia, and the Lello bookshop early or late. The trams are the nicest way to see the city.\"],[\"seville\",\"the Alcázar (book ahead), the cathedral and oranges everywhere in the streets of Santa Cruz. In high summer it is 40C, so sightsee before 11am and after 7pm.\"],[\"copenhagen\",\"Nyhavn for the picture, Tivoli if it's open, and the food market at Torvehallerne. Bikes are the real way to get around; hire one.\"],[\"stockholm\",\"Gamla Stan, the Vasa ship museum, and a ferry out to one of the islands. Everything is walkable in the centre.\"],[\"athens\",\"the Acropolis first thing with a timed ticket, the Acropolis Museum, and the Plaka in the evening. It is hot and shadeless up there, so take water and a hat.\"],[\"istanbul\",\"Hagia Sophia, the Blue Mosque and the Grand Bazaar on the old side, and a ferry across to Asia for lunch. Buy an Istanbulkart for the trams and ferries.\"],[\"new york\",\"pick two neighbourhoods a day: the High Line and Chelsea, the Lower East Side, and Brooklyn across the bridge. Book the big attractions online and walk a lot.\"],[\"tokyo\",\"one district a day: Shibuya and Shinjuku, Asakusa and Ueno, and Tsukiji or Toyosu for breakfast. Get a Suica card for the trains and carry cash for small places.\"],[\"kyoto\",\"Fushimi Inari at 7am before the crowds, the bamboo grove early too, and Gion at dusk. Buses are slow and packed: the subway plus walking is better.\"],[\"reykjavik\",\"the harbour and Hallgrímskirkja, and use the city as a base for the Golden Circle. Book the Blue Lagoon ahead and don't rinse the cave water off in the showers.\"],[\"venice\",\"get lost in Cannaregio and Dorsoduro away from St Mark's, cross the Grand Canal on the traghetto, and go early or late. Day-trippers leave by 5pm and the city feels completely different.\"],[\"boston\",\"walk the Freedom Trail, eat in the North End, and cross to Cambridge for a half-day. The T is small and easy.\"],[\"bath\",\"the Roman baths and the Pump Room, the Royal Crescent and the Circus, and a walk along the canal. It is small enough for a day, and the baths sell timed tickets that are worth booking the night before.\"],[\"ljubljana\",\"the riverside cafes and the Triple Bridge, the castle on the hill for the view, and a walk through Tivoli park. It is small and flat, so a day covers it before you head out to Lake Bled.\"],[\"krakow\",\"the main square and the cloth hall, Wawel castle, and Kazimierz for food and bars. Book Auschwitz-Birkenau a few days ahead and take the early bus: it is a full half-day.\"],[\"budapest\",\"the parliament and the Danube bank, the thermal baths (Szechenyi or Gellert), and the ruin bars in the old Jewish quarter. Buy a travel card for the trams and metro; the city is long, not wide.\"],[\"brussels\",\"the Grand Place, the comic-strip museum and the art nouveau houses, with the waffles and fries people come for. Two days covers it, and Bruges or Ghent is an hour away by train.\"],[\"milan\",\"the Duomo and its roof terraces, the Last Supper (book weeks ahead) and the Navigli canals in the evening. Most people use it as a base: Lake Como is an hour by train.\"],[\"naples\",\"the archaeology museum first, then pizza in the old town, and Pompeii or Herculaneum on a day trip by train. It is loud and fast, so keep bags in front of you and use the metro rather than the buses.\"],[\"munich\",\"Marienplatz and the English Garden, the beer halls, and a day out to Neuschwanstein or Dachau if you have the time. The trains are excellent; buy a day ticket rather than singles.\"],[\"zurich\",\"the old town on both sides of the river, a boat on the lake and the view from Uetliberg. Everything is expensive, so eat lunch from a bakery or a supermarket counter and save the restaurants for one evening.\"],[\"oslo\",\"the opera house roof you can walk on, the Vigeland park and the fjord boats. It is compact but pricey: buy a seven-day transport pass, and take the train to Bergen if you have three days.\"],[\"helsinki\",\"the cathedral square, the market hall and the design district, with a ferry to Suomenlinna for half a day. In summer the evenings are light until midnight, so eat late.\"],[\"tallinn\",\"the walled old town, the viewing platforms on Toompea, and the cafes in Kalamaja. A day covers the old town; take a ferry to Helsinki or a bus to Riga if you have longer.\"],[\"dubrovnik\",\"walk the city walls early or after 5pm once the cruise crowds have gone, then the cable car for the view. Take water and a hat up there, and swim off the rocks by the Buza gate.\"],[\"marrakech\",\"the Jemaa el-Fna at dusk, the Bahia palace and the Ben Youssef school, and a hammam. Agree taxi prices before you get in, and buy in the souks slowly: the first price is never the price.\"],[\"santorini\",\"Oia for the sunset once, but stay in Imerovigli or Pyrgos so you can sleep, and take a boat out to the volcano. Book months ahead for July and August, or come in May or September for the same light and half the people.\"],[\"valencia\",\"the City of Arts and Sciences, the old town round the cathedral, and the beach a short tram ride away. This is the home of paella, so eat it at lunch, not in the evening.\"],[\"granada\",\"the Alhambra first (book weeks ahead, it sells out), then the Albaicin at sunset from the San Nicolas viewpoint, with free tapas with drinks. Two nights is right: one is not enough for both.\"],[\"san sebastian\",\"the two beaches, the pintxos bars in the old town, and the walk up Monte Igueldo for the view. Eat standing at the bar: one or two pintxos a place, then move on.\"],[\"san francisco\",\"the Golden Gate on foot or by bike, the ferry building, and one neighbourhood properly rather than five badly. Layers matter: the fog rolls in and the temperature drops ten degrees by the water.\"],[\"chicago\",\"the architecture boat tour, the Art Institute and the river walk, then deep dish once for the experience. The Loop is walkable and the trains from O'Hare run all night.\"],[\"los angeles\",\"pick two areas and expect to drive between them: Venice or Santa Monica, the Griffith observatory at sunset, and one studio tour if you want one. It is far bigger than it looks on a map.\"],[\"toronto\",\"the islands for the skyline view, Kensington market and the Distillery district, and the St Lawrence market for lunch. The streetcars work well, and Niagara Falls is a day trip by train.\"],[\"sydney\",\"the harbour walk from the Opera House to Mrs Macquarie's chair, the Bondi to Coogee coastal path, and the ferry to Manly. Use the ferries as sightseeing: the Opal card caps the day.\"],[\"singapore\",\"the hawker centres for every meal, Gardens by the Bay in the evening, and the southern ridges walk. It is hot and humid all year, so walk early and save the air-conditioned museums for midday.\"],[\"bangkok\",\"the Grand Palace and Wat Pho early, the river boats rather than taxis, and street food in Chinatown at night. April and May are the hottest months, and from June the rain comes in short afternoon bursts.\"],[\"dubai\",\"the old creek and its abra boats, the desert at sunset, and one tall building rather than three. From June to September it is over 40C and people live indoors; November to March is the season.\"],[\"cape town\",\"Table Mountain first thing if the cloud is off it, the Cape Point drive, and Bo-Kaap and the V&A for the afternoon. The wind and cloud decide your plan, so keep the mountain day flexible.\"],[\"mexico city\",\"the Zocalo and the Templo Mayor, the Frida Kahlo house in Coyoacan, and the food markets. It sits at 2,240m, so take the first day slowly, and use the metro in the day and taxis at night.\"],[\"havana\",\"the old town in the morning, the Malecon at sunset, and a 1950s car once for the ride rather than the tour. Bring cash: foreign cards often do not work, so take enough for the whole trip.\"],[\"buenos aires\",\"Recoleta and the cemetery, San Telmo on a Sunday for the market, and a steak and a tango show in the evening. People eat at 10pm, so shift your day later or you will be dining alone.\"],[\"rio de janeiro\",\"Copacabana and Ipanema for the beach, Sugarloaf and Christ the Redeemer early before the crowds, and Santa Teresa for the afternoon. Take nothing valuable to the beach and use the metro after dark.\"],[\"hanoi\",\"the old quarter on foot with a pho stop, Hoan Kiem lake in the morning, and a coffee on a balcony over the traffic. Cross the road by walking steadily: the mopeds go round you, not through you.\"],[\"manchester\",\"the Northern Quarter for food and records, the Museum of Science and Industry in the old station, and a tram out to Salford Quays for the Lowry and the Imperial War Museum North. Book the Old Trafford or Etihad tour ahead.\"],[\"liverpool\",\"the Albert Dock and the two cathedrals, the Cavern and the Beatles Story if you want the music, and the ferry across the Mersey for the skyline. The Walker and the World Museum are free.\"],[\"birmingham\",\"the canals round Brindleyplace, the museum and art gallery, and a curry in the Balti Triangle rather than the middle of town. The library roof is free and has the best view in the city.\"],[\"leeds\",\"the Victoria Quarter and Kirkgate Market in the centre, then Headingley or Chapel Allerton for dinner. The Royal Armouries is free, and so are the city's galleries.\"],[\"sheffield\",\"the Winter Garden and the Peace Gardens, then Kelham Island for food and a brewery tap. The Peak District is half an hour by bus, which is the reason most people go.\"],[\"newcastle\",\"the Quayside and the Millennium Bridge, Grainger Town for the arcades, and the Baltic in Gateshead for the view. The metro to Tynemouth is a good half day at the coast.\"],[\"nottingham\",\"the castle and the Trip to Jerusalem, which is built into the rock, then Hockley for food and shops. Wollaton Hall and its deer park are free and a good hour.\"],[\"bristol\",\"the harbourside and the SS Great Britain, the Clifton Suspension Bridge, and Wapping Wharf or Stokes Croft for food. It is a walking city; the buses are the weak point.\"],[\"brighton\",\"the pier and the pebble beach, the Lanes for shops and the North Laine for food. The i360 is the view and the South Downs are a short bus ride.\"],[\"york\",\"the Minster, the Shambles and the city walls, which take an hour and cost nothing. Book the Minster and the Jorvik ahead in summer.\"],[\"glasgow\",\"Kelvingrove and the Burrell Collection, the Necropolis for the view, and the West End for food. The subway is a single loop and gets you round the centre.\"],[\"cardiff\",\"the castle in the middle of town, the old arcades for covered shopping streets, and Cardiff Bay for the waterfront. The national museum is free.\"],[\"belfast\",\"the Titanic museum on the old slipway, the Cathedral Quarter for pubs, and a black taxi tour if you want the history. The Giant's Causeway is a day out north.\"],[\"cork\",\"the English Market for lunch, St Anne's tower for the bells, and a pint in the old town. Kinsale and Cobh are short bus or train trips.\"],[\"galway\",\"the Latin Quarter for pubs and buskers, the Claddagh walk along the water, and a day on Inishmore or in Connemara. Book the Aran ferry ahead in summer.\"]]}")?;
frame.store("CITIES", __v_195.clone())?;
let __v_196 = pyrt::literals::decode("{\"$dict\":[[\"spain\",{\"$tuple\":[\"Spain\",\"Barcelona for a city and a beach in one trip. Seville for the Alcázar and the tapas. Madrid for the museums, with Toledo a short train ride away.\"]}],[\"italy\",{\"$tuple\":[\"Italy\",\"Rome for the ancient city and the Vatican. Florence for the art you can walk between. Naples and the Amalfi coast for pizza and sea.\"]}],[\"france\",{\"$tuple\":[\"France\",\"Paris for the museums and the food. Lyon for the best eating in the country. Provence for small towns and markets, and don't rush it.\"]}],[\"portugal\",{\"$tuple\":[\"Portugal\",\"Lisbon for trams, tarts and the river. Porto for the port cellars and the bookshop. The Algarve for beaches and cliffs.\"]}],[\"greece\",{\"$tuple\":[\"Greece\",\"Athens for the Acropolis and street food. Santorini for the view. Naxos for beaches and cheaper rooms.\"]}],[\"japan\",{\"$tuple\":[\"Japan\",\"Tokyo for the city and the food. Kyoto for temples and old streets. Osaka for eating, with a rail pass once you visit more than one.\"]}],[\"netherlands\",{\"$tuple\":[\"The Netherlands\",\"Amsterdam for the canals and the museums. Haarlem or Delft as a quieter base. The country is small, so everywhere is easy to reach.\"]}],[\"germany\",{\"$tuple\":[\"Germany\",\"Berlin for the history and the nightlife. Munich for beer gardens and the Alps. The Rhine and Mosel valleys for small wine towns.\"]}],[\"ireland\",{\"$tuple\":[\"Ireland\",\"Dublin for a city break. Galway and the Burren if you fly into Shannon. The west is the trip.\"]}],[\"scotland\",{\"$tuple\":[\"Scotland\",\"Edinburgh for the castle and the Old Town. The Highlands for lochs and mountains. A car helps north of the cities.\"]}],[\"england\",{\"$tuple\":[\"England\",\"London for the museums and the markets. Bath for the Roman baths. The Lake District for hills and walking.\"]}],[\"turkey\",{\"$tuple\":[\"Turkey\",\"Istanbul for mosques, bazaars and the ferries up the Bosphorus. Cappadocia for the balloon flights at sunrise. The coast if you want to swim.\"]}],[\"morocco\",{\"$tuple\":[\"Morocco\",\"Marrakech for the medina and the food. Fes for the crafts and the old city. Essaouira for the coast and the wind.\"]}],[\"croatia\",{\"$tuple\":[\"Croatia\",\"Split for a Roman palace and ferries to the islands. Dubrovnik for the walls, early before the crowds. Zadar for quieter evenings.\"]}],[\"iceland\",{\"$tuple\":[\"Iceland\",\"Reykjavik for the city. The south coast to Vik for waterfalls and black-sand beaches. The ring road takes longer than most people think.\"]}],[\"norway\",{\"$tuple\":[\"Norway\",\"Oslo for the museums and the opera house. The train to Bergen for the fjords, because the journey is half the point. Tromsø in winter for the northern lights.\"]}],[\"thailand\",{\"$tuple\":[\"Thailand\",\"Bangkok for temples and street food. Chiang Mai for the north. A flight south for the islands.\"]}],[\"mexico\",{\"$tuple\":[\"Mexico\",\"Mexico City for the food and the museums. Oaxaca for markets and mezcal. Tulum if you mainly want the beach.\"]}],[\"united states\",{\"$tuple\":[\"The States\",\"New York for a first trip. San Francisco and the coast for California. Chicago for food and the lake in summer.\"]}],[\"india\",{\"$tuple\":[\"India\",\"Delhi for the history. Jaipur and Jodhpur for Rajasthan. Kerala for the backwaters, and one region rather than criss-crossing the country.\"]}],[\"australia\",{\"$tuple\":[\"Australia\",\"Sydney for the harbour and the beaches. Melbourne for food, with the Great Ocean Road from there. Flying between the cities is normal.\"]}],[\"egypt\",{\"$tuple\":[\"Egypt\",\"Cairo for the pyramids and the museum. Luxor for the temples and the Valley of the Kings. Aswan for a slower stretch by the river.\"]}],[\"canada\",{\"$tuple\":[\"Canada\",\"Toronto and Montreal for cities. Banff and Jasper for the Rockies. Vancouver if you want sea and mountains together.\"]}],[\"czechia\",{\"$tuple\":[\"Czechia\",\"Prague for the old town and the castle. Český Krumlov for a smaller, quieter base. Brno for wine and fewer tourists.\"]}],[\"hungary\",{\"$tuple\":[\"Hungary\",\"Budapest for the baths, the ruin bars and the parliament. The Danube bend if you want a break from the city. Lake Balaton in summer.\"]}],[\"poland\",{\"$tuple\":[\"Poland\",\"Kraków for the old town, with Auschwitz as a sobering trip out. Warsaw for the rebuilt city and the museums. Gdańsk for the coast.\"]}],[\"austria\",{\"$tuple\":[\"Austria\",\"Vienna for the palaces and the coffee houses. Salzburg for the old town and the hills. Innsbruck for the Alps.\"]}],[\"switzerland\",{\"$tuple\":[\"Switzerland\",\"Zurich or Lucerne as a base. The Bernese Oberland for the mountain trains. A rail pass pays off fast.\"]}],[\"belgium\",{\"$tuple\":[\"Belgium\",\"Brussels briefly, for the Grand Place and the museums. Bruges for the canals, and Ghent for the same with fewer people. Both are short train rides from Brussels.\"]}],[\"sweden\",{\"$tuple\":[\"Sweden\",\"Stockholm for the islands and the museums. The archipelago in summer. Gothenburg for a second city.\"]}],[\"denmark\",{\"$tuple\":[\"Denmark\",\"Copenhagen for the city and the food. Aarhus for a second city. Malmö is a train ride over the bridge.\"]}],[\"finland\",{\"$tuple\":[\"Finland\",\"Helsinki for the design and the saunas. Lapland in winter for the snow and the northern lights. A summer cabin by a lake in the other season.\"]}],[\"new zealand\",{\"$tuple\":[\"New Zealand\",\"Queenstown and the southern lakes for the mountains. The North Island for beaches and volcanoes. Pick one island rather than trying both.\"]}],[\"china\",{\"$tuple\":[\"China\",\"Beijing for the Wall and the Forbidden City. Xi'an for the terracotta army. Shanghai for a city you can walk.\"]}],[\"vietnam\",{\"$tuple\":[\"Vietnam\",\"Hanoi for the old quarter and the food. Hoi An and the coast by train or a short flight south. Ha Long Bay for limestone islands and a boat.\"]}],[\"dubai\",{\"$tuple\":[\"Dubai\",\"A short trip: the old creek and the souks in the morning. The desert in the evening. One big mall, and the marina at night.\"]}],[\"singapore\",{\"$tuple\":[\"Singapore\",\"The hawker centres first. Gardens by the Bay after dark. A walk round Tiong Bahru for the old flats and the coffee.\"]}],[\"cape town\",{\"$tuple\":[\"Cape Town\",\"Table Mountain on a clear morning. The Cape peninsula drive. The winelands for the wine farms, and a car to do any of it.\"]}],[\"cuba\",{\"$tuple\":[\"Cuba\",\"Havana for the old town and the cars. Viñales for tobacco country. Take cash, because cards barely work.\"]}],[\"argentina\",{\"$tuple\":[\"Argentina\",\"Buenos Aires for the food and the nightlife. Mendoza for wine. Patagonia if you have the time.\"]}],[\"brazil\",{\"$tuple\":[\"Brazil\",\"Rio for the beaches and the views. The Pantanal for wildlife. Salvador for music and the old town.\"]}]]}")?;
