let __v_311 = pyrt::literals::decode("{\"$dict\":[[\"abu dhabi\",\"dubai\"],[\"ait benhaddou\",\"marrakech\"],[\"akrotiri\",\"santorini\"],[\"auschwitz-birkenau\",\"krakow\"],[\"aveiro\",\"porto\"],[\"ayutthaya\",\"bangkok\"],[\"baden\",\"vienna\"],[\"beacon\",\"new york\"],[\"bergamo\",\"milan\"],[\"bilbao\",\"san sebastian\"],[\"bradford-on-avon\",\"bath\"],[\"braga\",\"porto\"],[\"bratislava\",\"vienna\"],[\"brighton\",\"london\"],[\"bruges\",\"brussels\"],[\"burano\",\"venice\"],[\"bursa\",\"istanbul\"],[\"buzios\",\"rio de janeiro\"],[\"cambridge\",\"london\"],[\"cape sounion\",\"athens\"],[\"cascais\",\"lisbon\"],[\"cesky krumlov\",\"prague\"],[\"chartres\",\"paris\"],[\"chester\",\"manchester\"],[\"cholula\",\"mexico city\"],[\"concord\",\"boston\"],[\"cordoba\",\"seville\"],[\"delphi\",\"athens\"],[\"drobak\",\"oslo\"],[\"durnstein\",\"vienna\"],[\"el escorial\",\"madrid\"],[\"essaouira\",\"marrakech\"],[\"esztergom\",\"budapest\"],[\"franschhoek\",\"cape town\"],[\"getaria\",\"san sebastian\"],[\"geysir\",\"reykjavik\"],[\"ghent\",\"brussels\"],[\"girona\",\"barcelona\"],[\"giverny\",\"paris\"],[\"glasgow\",\"edinburgh\"],[\"guimaraes\",\"porto\"],[\"haarlem\",\"amsterdam\"],[\"halong bay\",\"hanoi\"],[\"harrogate\",\"leeds\"],[\"hatta\",\"dubai\"],[\"herculaneum\",\"naples\"],[\"hermanus\",\"cape town\"],[\"hikone\",\"kyoto\"],[\"howth\",\"dublin\"],[\"interlaken\",\"zurich\"],[\"ischia\",\"naples\"],[\"jerez\",\"seville\"],[\"kamakura\",\"tokyo\"],[\"kanchanaburi\",\"bangkok\"],[\"karlstejn\",\"prague\"],[\"krka\",\"split\"],[\"kutna hora\",\"prague\"],[\"lacock\",\"bath\"],[\"lake balaton\",\"budapest\"],[\"lake bled\",\"ljubljana\"],[\"lake como\",\"milan\"],[\"leuven\",\"brussels\"],[\"lexington\",\"boston\"],[\"liverpool\",\"manchester\"],[\"loch lomond\",\"glasgow\"],[\"lucca\",\"florence\"],[\"lucerne\",\"zurich\"],[\"malacca\",\"singapore\"],[\"matanzas\",\"havana\"],[\"milwaukee\",\"chicago\"],[\"montenegro\",\"dubrovnik\"],[\"montserrat\",\"barcelona\"],[\"muir woods\",\"san francisco\"],[\"nara\",\"kyoto\"],[\"neuschwanstein\",\"munich\"],[\"niagara falls\",\"toronto\"],[\"niagara-on-the-lake\",\"toronto\"],[\"nikko\",\"tokyo\"],[\"ninh binh\",\"hanoi\"],[\"niteroi\",\"rio de janeiro\"],[\"north berwick\",\"edinburgh\"],[\"obidos\",\"lisbon\"],[\"oia\",\"santorini\"],[\"orvieto\",\"rome\"],[\"osaka\",\"kyoto\"],[\"ostia antica\",\"rome\"],[\"oxford\",\"london\"],[\"padua\",\"venice\"],[\"petropolis\",\"rio de janeiro\"],[\"philadelphia\",\"new york\"],[\"pisa\",\"florence\"],[\"pompeii\",\"naples\"],[\"porvoo\",\"helsinki\"],[\"postojna\",\"ljubljana\"],[\"potsdam\",\"berlin\"],[\"providence\",\"boston\"],[\"puebla\",\"mexico city\"],[\"requena\",\"valencia\"],[\"ronda\",\"seville\"],[\"roskilde\",\"copenhagen\"],[\"sachsenhausen\",\"berlin\"],[\"sagunto\",\"valencia\"],[\"salem\",\"boston\"],[\"salzburg\",\"munich\"],[\"santa monica\",\"los angeles\"],[\"sausalito\",\"san francisco\"],[\"segovia\",\"madrid\"],[\"siena\",\"florence\"],[\"sintra\",\"lisbon\"],[\"sitges\",\"barcelona\"],[\"skocjan\",\"ljubljana\"],[\"stellenbosch\",\"cape town\"],[\"stirling\",\"edinburgh\"],[\"stonehenge\",\"bath\"],[\"stratford\",\"toronto\"],[\"stratford-upon-avon\",\"birmingham\"],[\"szentendre\",\"budapest\"],[\"tartu\",\"tallinn\"],[\"taxco\",\"mexico city\"],[\"teotihuacan\",\"mexico city\"],[\"the albufera\",\"valencia\"],[\"the blue mountains\",\"sydney\"],[\"tigre\",\"buenos aires\"],[\"tivoli\",\"rome\"],[\"toledo\",\"madrid\"],[\"trogir\",\"split\"],[\"turin\",\"milan\"],[\"uppsala\",\"stockholm\"],[\"utrecht\",\"amsterdam\"],[\"verona\",\"venice\"],[\"versailles\",\"paris\"],[\"vinales\",\"havana\"],[\"wells\",\"bristol\"],[\"york\",\"leeds\"],[\"zakopane\",\"krakow\"]]}")?;
frame.store("DAY_TRIP_PLACES", __v_311.clone())?;
let __v_312 = pyrt::literals::decode("{\"$dict\":[[\"pompeii\",\"Give Pompeii most of a day: it is 66 hectares and there is no shade, so go at opening time, take water and wear shoes with grip. Book a timed ticket and the train from Naples on the Circumvesuviana; the audioguide is worth it and the walk to the amphitheatre is the quiet half.\"],[\"herculaneum\",\"Herculaneum takes two or three hours rather than a day, and the woodwork, frescoes and upper floors survived in a way Pompeii's did not, so it is the better visit if you have one afternoon. It is the same train line as Pompeii, one stop closer to Naples, and the site is small enough to see in one go.\"],[\"vesuvius\",\"Vesuvius is a bus up from Ercolano and a steep 20-minute walk from the car park, with the crater rim roped off. Go on a clear morning, take a jacket because it is cold and windy at the top, and check the bus times for the way back: the last one leaves early.\"],[\"alhambra\",\"The Alhambra is a half day and the Nasrid palaces need a timed slot booked weeks ahead, in the morning if you can. Take your passport or ID card: it is checked against the ticket, and people are turned away without it.\"],[\"colosseum\",\"The Colosseum together with the Forum and Palatine is one ticket and most of a day, so start early and take water. Book the timed entry and the underground or arena add-on if you want them, because they sell out first.\"],[\"stonehenge\",\"Stonehenge is two hours at most, and the stones are seen from a path rather than walked among. Book a timed slot including the shuttle from the visitor centre, and pair it with Avebury or Salisbury if you are driving that far.\"],[\"eiffel tower\",\"The Eiffel Tower wants a booked time slot and two to three hours with the queues and the lifts, or 45 minutes if you walk up to the second floor. The stairs are cheaper and shorter, and the last lift up is around 11pm.\"],[\"vatican museums\",\"The Vatican Museums and the Sistine Chapel are three hours at a fast walk and half a day at a normal one, so book the first entry of the day. Cover your shoulders and knees, and note the chapel is silent with no photographs.\"],[\"sagrada familia\",\"The Sagrada Familia needs a timed ticket bought online, and an hour and a half inside. Add the tower lift if you want it - it is a separate ticket - and go in the morning when the east windows are lit.\"],[\"auschwitz\",\"Auschwitz-Birkenau is a heavy half day, five or six hours with the bus, and the timed entry must be booked ahead. Go with a guide, take tissues, and plan something gentle for afterwards.\"]]}")?;
frame.store("SITE_NOTES", __v_312.clone())?;
let __v_313 = { let __dict_314 = Value::dict(); let __v_315 = Value::from("vatican"); let __v_316 = Value::from("vatican museums"); __dict_314.dict_set(__v_315, __v_316)?; let __v_317 = Value::from("the vatican"); let __v_318 = Value::from("vatican museums"); __dict_314.dict_set(__v_317, __v_318)?; let __v_319 = Value::from("sistine chapel"); let __v_320 = Value::from("vatican museums"); __dict_314.dict_set(__v_319, __v_320)?; __dict_314 };
frame.store("SITE_ALIASES", __v_313.clone())?;
let __v_321 = pyrt::literals::decode("{\"$dict\":[[{\"$tuple\":[\"naples\",\"sorrento\"]},\"Naples to Sorrento: the Circumvesuviana train from Napoli Garibaldi takes about an hour and costs a few euros, and it is crowded with luggage at commuter times. The fast ferry from Molo Beverello is 35 to 45 minutes and pleasanter, but it runs only in season.\"],[{\"$tuple\":[\"naples\",\"amalfi\"]},\"Naples to the Amalfi coast: the season ferry from Molo Beverello to Amalfi or Positano is the pretty way and takes 75 minutes; the SITA bus from Sorrento or Salerno is cheaper and slower, and the coast road is the part that jams in summer. A car is a liability in August.\"],[{\"$tuple\":[\"sorrento\",\"amalfi\"]},\"Sorrento to Amalfi: the SITA bus along the coast road is about 90 minutes and the ferry is 25, but the ferry runs from spring to October only. Sit on the left of the bus going east for the view, and buy the ticket before you queue.\"],[{\"$tuple\":[\"rome\",\"pompeii\"]},\"Rome to Pompeii: the fast train to Naples takes 70 minutes, then the Circumvesuviana to Pompeii Scavi, so about two and a half hours door to door and a long day. Herculaneum is the same trip and half the walking.\"],[{\"$tuple\":[\"naples\",\"pompeii\"]},\"Naples to Pompeii: the Circumvesuviana from Napoli Garibaldi to Pompeii Scavi takes 35 to 40 minutes and drops you at the site gate. Get off at Pompeii Scavi, not Pompei town, and keep your bag in front of you on the train.\"],[{\"$tuple\":[\"florence\",\"pisa\"]},\"Florence to Pisa: the regional train from Santa Maria Novella takes about an hour and the tower is a 20-minute walk from Pisa Centrale. Book the tower climb separately and go early, because the slots are timed and the station is far from the airport side.\"],[{\"$tuple\":[\"london\",\"paris\"]},\"London to Paris: the Eurostar from St Pancras is two hours twenty to the Gare du Nord, city centre to city centre, and the cheapest fares go on sale months ahead. Check in 75 to 90 minutes before, and the coach is cheaper but a whole day.\"]]}")?;
frame.store("ROUTE_BETWEEN", __v_321.clone())?;
let __v_322 = pyrt::literals::decode("{\"$dict\":[[\"amalfi coast\",\"Getting to the Amalfi coast: fly to Naples, then the ferry from Molo Beverello to Amalfi or Positano in season, or the Circumvesuviana train to Sorrento and the SITA bus along the coast. A private transfer is the only sensible option with heavy luggage.\"],[\"cinque terre\",\"Getting to the Cinque Terre: trains from Pisa or Genoa run to La Spezia, then the local line stops at each village. Parking is almost impossible in the villages, so leave the car at La Spezia or Levanto.\"],[\"machu picchu\",\"Getting to Machu Picchu: fly or bus to Cusco, then the train from Poroy or Ollantaytambo to Aguas Calientes, then the bus up. The Inca Trail needs a permit booked months ahead with a licensed operator, and entry tickets are timed.\"],[\"great barrier reef\",\"Getting to the reef: fly to Cairns or Port Douglas and take a day boat from the marina, or go out from Airlie Beach in the Whitsundays. Book two days ahead, take the seasickness tablets before you board.\"],[\"isle of skye\",\"Getting to Skye: drive over the bridge from Kyle of Lochalsh, or take the train to Kyle and the bus, or the ferry from Mallaig to Armadale. Book accommodation months ahead for summer and expect single-track roads.\"]]}")?;
frame.store("GET_TO", __v_322.clone())?;
let __v_323 = pyrt::literals::decode("{\"$dict\":[[\"london\",\"Tap a contactless card or phone on the bus and the Tube and it charges the cheapest fare of the day, with a daily cap, so a paper travelcard rarely beats it. Buses are a flat £1.75 and take no cash.\"],[\"paris\",\"Get a Navigo Easy card and load ten tickets: a single is €2.15 and ten is cheaper, and it covers the Metro inside the city. Keep the ticket until you are out of the gate, because inspectors fine on the spot.\"],[\"rome\",\"A ticket is €1.50 and lasts 100 minutes on the metro and the buses, validated in the machine on board. There are only two metro lines, so walk the centre and take a bus for the rest.\"],[\"milan\",\"A €2.20 ticket covers 90 minutes of metro, trams and buses, and you can tap a bank card at the metro gate. The centre is small enough to walk, the metro is for the outer bits.\"],[\"florence\",\"Walk: the historic centre is 20 minutes across and a car is a liability. A bus ticket is €1.50 for 90 minutes, from a tabacchi or the app rather than the driver.\"],[\"venice\",\"The vaporetto is the road here: a single is €9.50 and a 24-hour pass about €25, so the pass pays off after two rides. Walk between the Rialto and San Marco and take the boat for the islands.\"],[\"naples\",\"A ticket is €1.10 and lasts 90 minutes on the metro, the buses and the funicular, bought at a tabacchi. Metro line 1 is worth riding for the art in the stations.\"],[\"barcelona\",\"A T-casual card is ten rides for about €12.50 but it is one person only: for two or more of you the T-familiar is eight rides over 30 days and can be passed back over the gate. The metro reaches nearly everything and runs late.\"],[\"madrid\",\"A ten-ride Metrobus card is the cheapest way to ride the metro and the buses, about €1.20 a trip, and the centre is walkable anyway. The metro is fast and air conditioned.\"],[\"seville\",\"Walk: the centre is flat and 20 minutes across. Beyond that a bus ticket is €1.40 and the tram crosses the old town, and bikes are easy to hire on the cycle lanes.\"],[\"valencia\",\"A metro ticket is €1.50 and gets you from the old town to the City of Arts; the centre itself is walkable and the old river bed is now a park you can walk through.\"],[\"granada\",\"Walk the centre and take a bus up the hill for the Alhambra: a ticket is €1.40 and the C30 and C32 go from the Plaza Nueva. Taxis are cheap for the station.\"],[\"san sebastian\",\"Everything is walkable: the two beaches are 15 minutes apart. A bus ticket is about €2 for the ride out to Monte Igueldo, and there is a funicular for the view.\"],[\"lisbon\",\"Get a Viva Viagem card from the machine and load it: a single is €1.85 and a 24-hour pass €6.80. Tram 28 is beautiful and pickpocketed, so ride it early or take the metro instead.\"],[\"porto\",\"An Andante card covers the metro and the buses at about €1.60 a trip, plus 60 cents for the card itself. The historic tram is a separate €3.50 and worth doing once.\"],[\"amsterdam\",\"Tap in and out with a contactless card or an OV-chipkaart: a trip inside the city is about €3.40 and forgetting to tap out costs you. The trams go everywhere and the centre is small.\"],[\"berlin\",\"A single AB ticket is €3.50 and a 24-hour ticket about €10, so the day ticket wins after three rides. There are no ticket gates and the inspectors do fine, so validate before you board.\"],[\"munich\",\"A single is €3.90 and a day ticket for the inner zone about €8.60; the U-Bahn and S-Bahn are the way round and both run late. Validate the ticket before you get on.\"],[\"prague\",\"A 30-minute ticket is 30 crowns and a 90-minute one 40, from a machine or the app, and you stamp it on the first ride. The trams are the best sightseeing in the city.\"],[\"vienna\",\"A single is €2.40 and a 48-hour pass about €14, which is what a weekend wants. The U-Bahn is fast, the Ringstrasse is a 40-minute walk, and you validate the ticket once.\"],[\"budapest\",\"A single is 350 forints and a 24-hour ticket about 2,500, from the machine, validated before you board. Tram 2 along the Danube is the best ride in the city and costs the same as any other.\"],[\"krakow\",\"The old town and the castle are walkable; a 20-minute bus or tram ticket is 4 zloty from a machine, and the airport train is separate. The trams are old and cheap.\"],[\"istanbul\",\"Get an Istanbulkart from the machine and top it up: a ride is about 20 lira on the card and nearly double as a single, and one card covers several people. The trams and the ferries go where the traffic will not.\"],[\"athens\",\"A ticket is €1.20 and lasts 90 minutes on the metro, the trolleybuses and the trams; the airport line is separate. The centre under the Acropolis is walkable and the hills are not.\"],[\"dublin\",\"A Leap card takes about 30% off, so a bus or tram ride is €2 on it rather than the cash fare. The centre is 20 minutes across on foot and the DART follows the coast.\"],[\"edinburgh\",\"Lothian buses are a flat £2 and you tap a card, with no change given. The old town and the new town are 15 minutes apart on foot, and the tram is only worth it for the airport.\"],[\"copenhagen\",\"Tickets are by zone and a 24-hour city pass is about 90 kroner; a bike is what everyone actually uses and most of the centre is a five-minute ride. The harbour bus is a cheap boat trip.\"],[\"stockholm\",\"A single on the SL is about 39 kronor and a 72-hour pass about 270; the T-bana is the way round and the old town is walkable. Tickets are cashless, so buy on the app or tap a card.\"],[\"oslo\",\"A single on Ruter is about 40 kroner and a 24-hour ticket about 120; the trams and the metro are clean and the centre is walkable. Buy on the app before boarding.\"],[\"helsinki\",\"A ticket inside the city is about €3 and a day ticket €9, and the trams cover the centre on their own. The ferry to Suomenlinna runs on the same ticket.\"],[\"reykjavik\",\"The centre is walkable and a bus ticket is about 630 kronur, needed only for the pools and the outer suburbs. Tours collect from stops near the hotels rather than the door, so check which stop is yours.\"],[\"zurich\",\"Buy by zone on the ZVV app or at a machine: a trip across the city is about 4.30 francs and there are no barriers. The trams go everywhere and run to the minute.\"],[\"brussels\",\"A single on the metro, tram or bus is €2.60 and you tap a bank card at the gate. The Grand Place is 20 minutes from most of the centre on foot.\"],[\"new york\",\"Tap a contactless card or phone on the turnstile: a subway ride is $2.90 whatever the distance and trains run all night. Take the express where there is one, because the local stops every block.\"],[\"chicago\",\"A Ventra card or a contactless tap is $2.50 a ride on the L and the buses, and most L lines run all night. The loop is walkable and the L is for everything outside it.\"],[\"boston\",\"A CharlieCard is $2.40 a ride on the T and contactless works at the gates too. The subway covers the centre and the Freedom Trail is a walk between the stops.\"],[\"san francisco\",\"Tap a Clipper card or a phone on Muni: $2.50 buys 90 minutes on the buses and the metro. BART is a separate fare for the airport, and the hills are real, so take the cable car once.\"],[\"los angeles\",\"A TAP card is $1.75 a ride and a day caps at about $5, and the metro is fine for Hollywood and Santa Monica. The traffic is the reason to plan, so stay near where you are going.\"],[\"toronto\",\"A PRESTO tap is about $3.30 for two hours of streetcars, buses and subway. The centre is walkable and the PATH tunnels keep you out of the weather.\"],[\"mexico city\",\"The metro is 5 pesos a ride on a card from the machine, fast and very crowded at rush hour. Uber is cheap and easier at night, and the pink line covers most of the centre.\"],[\"tokyo\",\"Get a Suica or Pasmo card, or add one to your phone: a metro ride is about 180 yen and the machines take cash. Trains stop around midnight, so plan the last one.\"],[\"kyoto\",\"Buses are a flat 230 yen and the subway is only two lines, so the bus does the temples. Tap an IC card, and walk the Gion and Higashiyama side rather than ride.\"],[\"osaka\",\"An ICOCA card or a phone covers the metro and the private lines, about 190 yen a ride. The loop line gets you round the centre and Dotonbori is walkable.\"],[\"seoul\",\"A T-money card is about 1,400 won a ride and works on the metro, the buses and in taxis. The metro is cheap, clean, signed in English and the fastest way across the city.\"],[\"bangkok\",\"Get a Rabbit card for the BTS Skytrain: a ride is 17 to 45 baht and it goes over the traffic rather than through it. The metro is a separate ticket, and the river boats are the cheapest way along the Chao Phraya.\"],[\"singapore\",\"Tap a contactless card on the MRT and the buses: a trip is about S$2 and the system is spotless. It stops around midnight, and a taxi or Grab after that.\"],[\"hong kong\",\"Get an Octopus card: it pays for the MTR, buses, ferries and shops, and a ride is about HK$10 to 20. The MTR is the fastest way anywhere and the Star Ferry is the cheapest sightseeing.\"],[\"sydney\",\"Tap on and off with a bank card or an Opal: a city trip is about A$4, and the train from the airport is a separate A$19. The ferries are the best value sightseeing in the city.\"],[\"melbourne\",\"A myki card or a contactless card covers trams, trains and buses at about A$5 for two hours, and the tram zone in the centre is free. Trams run through the night at weekends.\"],[\"dubai\",\"A Nol card covers the metro and the buses, and a ride is about 3 to 7.5 dirham. The metro is driverless and clean and goes to the malls; taxis are cheap by European standards.\"],[\"cape town\",\"There is no useful metro for visitors: use Uber or a MyCiTi bus, which is about 8 rand a trip on a card, and hire a car for the Winelands and the Cape. Agree the fare before you get in a taxi.\"],[\"vancouver\",\"A Compass card or a contactless tap covers the SkyTrain, the buses and the SeaBus, and a trip inside the city is about C$3.15. The SkyTrain from the airport costs a few dollars more, and the centre is walkable.\"],[\"marrakech\",\"Small taxis are the way round: 20 to 30 dirham inside the city, agreed before you get in. The medina is walkable and a guide the first day is money well spent.\"]]}")?;
