let __v_1145 = { let mut __items_1146 = Vec::new(); let __v_1147 = Value::from("which station"); __items_1146.push(__v_1147); let __v_1148 = Value::from("what station"); __items_1146.push(__v_1148); let __v_1149 = Value::from("closest station"); __items_1146.push(__v_1149); let __v_1150 = Value::from("nearest station"); __items_1146.push(__v_1150); let __v_1151 = Value::from("which stop"); __items_1146.push(__v_1151); let __v_1152 = Value::from("closest to"); __items_1146.push(__v_1152); let __v_1153 = Value::from("nearest to"); __items_1146.push(__v_1153); let __v_1154 = Value::from("closest one"); __items_1146.push(__v_1154); Value::tuple(__items_1146) };
frame.store("_ARRIVAL_PICK", __v_1145.clone())?;
let __v_1155 = Value::from("From the main station, take the metro, tram or airport-style express bus and leave the taxi for the cases and the late hour: in most European cities the ride from the main station to the centre is 2 to 5 euros and a taxi is 15 to 25. Buy the ticket at the machine or on the app before you board, walk to the official rank outside the main exit rather than taking an offer from someone inside, and have the address written down or on the phone screen.");
frame.store("_ARRIVAL_TOWN", __v_1155.clone())?;
let __v_1156 = Value::from("Check the last metro or bus before you travel - in most cities it is between half eleven and half twelve - and if it has gone, take the rank outside the station or ring the hotel and ask them to book a car, rather than getting in with someone who offers. Tell the hotel you will be late so they hold the room and give you the door code, and keep 20 euros of cash on you for the ride.");
frame.store("_ARRIVAL_LATE_NOTE", __v_1156.clone())?;
let __v_1157 = Value::from("Tap a contactless bank card or your phone if the city takes it, and you pay the local fare with no ticket to buy or validate; otherwise get a day or three-day travel card from the machine, which usually pays off after three or four rides. Validate the ticket or tap in at the start of every journey, because an unvalidated one counts as no ticket, and keep the same card for the way back so the daily cap applies.");
frame.store("_ARRIVAL_ABOUT_NOTE", __v_1157.clone())?;
let __v_1158 = Value::from("Pick the station named for the part you are staying in - the old town, the centre, the harbour - rather than the city's biggest one, and put both on a route planner before you book: the walk from the door to the hotel is the figure that decides it. A station with the city name plus a district in its name is usually the one closest to the old town.");
frame.store("_ARRIVAL_PICK_NOTE", __v_1158.clone())?;
